export function tDynamic(text: string | null | undefined, lang: Language): string {
  if (!text) return "";
  const trimmed = text.trim();
  if (DYNAMIC_LOOKUP[trimmed] && DYNAMIC_LOOKUP[trimmed][lang]) {
    return DYNAMIC_LOOKUP[trimmed][lang];
  }
  // Case-insensitive fallback lookup
  const lower = trimmed.toLowerCase();
  for (const key of Object.keys(DYNAMIC_LOOKUP)) {
    if (key.toLowerCase() === lower && DYNAMIC_LOOKUP[key][lang]) {
      return DYNAMIC_LOOKUP[key][lang];
    }
  }
  return text;
}

export function createLangDict(
  partial: Partial<TranslationDictionary>,
  base: TranslationDictionary = enDict
): TranslationDictionary {
  return { ...base, ...partial };
}

